package cn.zhuatech.bcm.service;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.assertThat;class ContinuityExerciseCertificationServiceTest{private final ContinuityExerciseCertificationService service=new ContinuityExerciseCertificationService();@Test void certifiesSuccessfulExercise(){var r=service.assess(new ContinuityExerciseCertificationService.Request("E1",true,120,90,30,10,true,true,true,0));assertThat(r.decision()).isEqualTo(ContinuityExerciseCertificationService.Decision.CERTIFY);}@Test void blocksRecoveryFailure(){var r=service.assess(new ContinuityExerciseCertificationService.Request("E2",false,60,120,10,30,false,true,false,0));assertThat(r.blockers()).hasSize(5);}@Test void remediatesCommunicationAndActions(){var r=service.assess(new ContinuityExerciseCertificationService.Request("E3",true,120,90,30,10,true,false,true,2));assertThat(r.actions()).hasSize(2);}}
